alter schema if exists schema1 rename to schema2;
alter schema schema1 swap with schema2;
alter schema schema2 enable managed access;
alter schema schema1 set data_retention_time_in_days = 3;
alter schema schema1 set tag tag1 = 'value1', tag2 = 'value2';
alter schema schema1 unset data_retention_time_in_days;
alter schema schema1 unset data_retention_time_in_days, max_data_extension_time_in_days;
alter schema schema1 unset tag foo, bar;

ALTER SCHEMA s1 SET LOG_LEVEL = 'DEBUG';
ALTER SCHEMA s1 SET TRACE_LEVEL = 'ALWAYS' STORAGE_SERIALIZATION_POLICY = OPTIMIZED;
ALTER SCHEMA IF EXISTS s1 SET
    EXTERNAL_VOLUME = 'my_volume'
    CATALOG = 'my_catalog'
    REPLACE_INVALID_CHARACTERS = TRUE
    DEFAULT_STREAMLIT_NOTEBOOK_WAREHOUSE = my_wh;
ALTER SCHEMA s1 SET CONTACT STEWARD = my_db.my_schema.steward_contact;
ALTER SCHEMA s1 UNSET LOG_LEVEL, STORAGE_SERIALIZATION_POLICY, COMMENT;
ALTER SCHEMA s1 UNSET DEFAULT_NOTEBOOK_COMPUTE_POOL_CPU, DEFAULT_NOTEBOOK_COMPUTE_POOL_GPU;
ALTER SCHEMA s1 UNSET CONTACT STEWARD;
ALTER SCHEMA s1 UNSET DCM PROJECT;

-- Iceberg parameters
ALTER SCHEMA s1 SET
    ICEBERG_DEFAULT_DDL_COLLATION = 'en-ci'
    ICEBERG_VERSION_DEFAULT = 3
    ICEBERG_MERGE_ON_READ_BEHAVIOR = 'ENABLED'
    ENABLE_ICEBERG_MERGE_ON_READ = TRUE;
ALTER SCHEMA s1 UNSET
    ICEBERG_DEFAULT_DDL_COLLATION,
    ICEBERG_VERSION_DEFAULT,
    ICEBERG_MERGE_ON_READ_BEHAVIOR,
    ENABLE_ICEBERG_MERGE_ON_READ;

-- Full SET example
ALTER SCHEMA IF EXISTS s1 SET
    DATA_RETENTION_TIME_IN_DAYS = 30
    MAX_DATA_EXTENSION_TIME_IN_DAYS = 14
    EXTERNAL_VOLUME = 'my_volume'
    CATALOG = 'my_catalog'
    REPLACE_INVALID_CHARACTERS = FALSE
    DEFAULT_DDL_COLLATION = 'en-ci'
    DEFAULT_NOTEBOOK_COMPUTE_POOL_CPU = 'cpu_pool'
    DEFAULT_NOTEBOOK_COMPUTE_POOL_GPU = 'gpu_pool'
    LOG_LEVEL = 'WARN'
    TRACE_LEVEL = 'ON_EVENT'
    STORAGE_SERIALIZATION_POLICY = COMPATIBLE
    CLASSIFICATION_PROFILE = 'my_db.my_schema.my_profile'
    COMMENT = 'Full example schema'
    CATALOG_SYNC = 'my_open_catalog_integration'
    REPLICABLE_WITH_FAILOVER_GROUPS = 'YES'
    BASE_LOCATION_PREFIX = 'prefix/path'
    DEFAULT_STREAMLIT_NOTEBOOK_WAREHOUSE = 'my_wh'
    CONTACT STEWARD = steward_contact, SUPPORT = support_contact
    OBJECT_VISIBILITY = PRIVILEGED
    ENABLE_DATA_COMPACTION = TRUE
    OAUTH_AUTHORIZATION_SERVER = my_external_oauth_integration
    OAUTH_SCOPES_SUPPORTED = 'read,write';

-- Full UNSET example
ALTER SCHEMA IF EXISTS s1 UNSET
    DATA_RETENTION_TIME_IN_DAYS,
    MAX_DATA_EXTENSION_TIME_IN_DAYS,
    EXTERNAL_VOLUME,
    CATALOG,
    REPLACE_INVALID_CHARACTERS,
    DEFAULT_DDL_COLLATION,
    LOG_LEVEL,
    TRACE_LEVEL,
    STORAGE_SERIALIZATION_POLICY,
    COMMENT,
    CATALOG_SYNC,
    REPLICABLE_WITH_FAILOVER_GROUPS,
    BASE_LOCATION_PREFIX,
    DEFAULT_STREAMLIT_NOTEBOOK_WAREHOUSE,
    CONTACT SUPPORT,
    CLASSIFICATION_PROFILE,
    OBJECT_VISIBILITY,
    ENABLE_DATA_COMPACTION,
    OAUTH_AUTHORIZATION_SERVER,
    OAUTH_SCOPES_SUPPORTED,
    DCM PROJECT;
